function cleanVisibleReply(value){return String(value||'').split(/\r?\n/).filter(line=>!/^\s*(?:user|content|response)\s+safety\s*:\s*(?:safe|unsafe)\s*$/i.test(line)).join('\n').replace(/\n{3,}/g,'\n\n').trim();}
function walletNetwork(text){if(/\b(?:TRC\s*20|TRON|TRX)\b|ترون/i.test(text))return 'TRC20';if(/\b(?:ERC\s*20|ETHEREUM|ETH)\b|إيثيريوم/i.test(text))return 'ERC20';if(/\b(?:BEP\s*20|BSC|BNB\s*CHAIN)\b|بينانس/i.test(text))return 'BEP20';if(/\b(?:SOLANA|SOL)\b|سولانا/i.test(text))return 'Solana';return '';}
function handleWalletChat(message){const asksForUsdt=/(?:USDT|تيثر|محفظة|عنوان|wallet|address)/i.test(message);if(asksForUsdt){const address=message.match(/\b0x[a-fA-F0-9]{40}\b|\bT[1-9A-HJ-NP-Za-km-z]{33}\b/);if(address){const network=walletNetwork(message);save(s=>{s.settings.usdtWalletAddress=address[0];s.settings.usdtNetwork=network;});save(s=>{s.messages.push({role:'user',content:'أرسلت عنوان استلام USDT (أُخفي من سجل المحادثة وحُفظ محليًا).'});s.messages.push({role:'assistant',content:network?`حفظت عنوان USDT محليًا على شبكة ${network}. لن أرسله لأي جهة قبل مراجعته منك.`:'حفظت العنوان محليًا مؤقتًا. اكتب اسم الشبكة فقط (TRC20 أو ERC20 أو BEP20) لأكمل حفظ بيانات الاستلام.'});s.messages=s.messages.slice(-80);});toast(network?'تم حفظ عنوان USDT على هذا الهاتف':'أرسل اسم شبكة USDT فقط الآن');return true;}}
 if(state.settings.usdtWalletAddress&&!state.settings.usdtNetwork){const network=walletNetwork(message);if(network){save(s=>{s.settings.usdtNetwork=network;s.messages.push({role:'user',content:`الشبكة: ${network}`});s.messages.push({role:'assistant',content:`تم حفظ شبكة ${network} مع عنوان USDT على هذا الهاتف. لن أشارك العنوان أو أرسل أموالًا.`});s.messages=s.messages.slice(-80);});toast('اكتمل حفظ بيانات استلام USDT محليًا');return true;}}
 return false;}
