function makeSearches(q,selected=''){const wanted=selected?categories.filter(x=>x[0]===selected):categories;return wanted.map(([code,label])=>({code,query:[searchTerms[code]||label,q.trim(),'freelance contract remote'].filter(Boolean).join(' ')}));}
function beginSearch(plan){if(!plan.length)return;selectedResultUrls.clear();if(selectedAddBtn)selectedAddBtn.disabled=true;if(selectedCountEl)selectedCountEl.textContent='المحدد: 0';results=[];searchErrors=[];searchAttempted=[];searchExcluded=0;searchServerOutdated=false;searchPlan=plan.slice();searchCategory='';toast(`البحث عن مشاريع مستقلة عن بُعد في ${plan.length} أقسام…`);runNextSearch();}
function amountSorted(list){return list.slice().sort((a,b)=>{const ac=Number.isSafeInteger(a.amountCents)?a.amountCents:-1,bc=Number.isSafeInteger(b.amountCents)?b.amountCents:-1;if(a.currency!==b.currency)return String(a.currency||'ZZZ').localeCompare(String(b.currency||'ZZZ'));if((a.basis||'ZZZ')!==(b.basis||'ZZZ'))return String(a.basis||'ZZZ').localeCompare(String(b.basis||'ZZZ'));return bc-ac;});}
