 for(const [code,label]of categories){const section=card(main,label);section.append(button('ابحث عن عقود وفرص: '+label,()=>beginSearch(makeSearches(query.value.trim(),code)),'primary'));const group=amountSorted(results.filter(r=>r.category===code));if(!group.length){const status=searchErrors.includes(code)?'تعذّر البحث في هذا القسم. افتح الإعدادات واضغط «اختبار الخادم والبحث» لمعرفة السبب.':searchAttempted.includes(code)?'لم يظهر إعلان مستوفٍ لشروط المشروع المستقل عن بُعد في نتائج محرك البحث لهذه المحاولة؛ لم نعرض وظائف توظيف بدلًا منه. جرّب تخصصًا أو كلمات أدق.':'لم يُبحث هذا القسم في هذه الجلسة بعد.';section.append(el('p',status,'muted'));continue;}const keys=[...new Set(group.map(r=>(r.currency||'UNKNOWN')+'|'+(r.basis||'UNKNOWN')))];for(const key of keys){const pair=key.split('|'),currency=pair[0],rate=pair[1];section.append(el('h3',currency==='UNKNOWN'?'العملة غير المعلنة':currency+' · '+(rate==='HOURLY'?'أجر بالساعة':rate==='FIXED'?'مبلغ ثابت':'نوع السعر غير معلن')));const items=group.filter(r=>(r.currency||'UNKNOWN')===currency&&(r.basis||'UNKNOWN')===rate);for(const [i,r]of items.entries())resultCard(section,r,i);}}
